const {dependency,root,fixture,loadExperience}=require('./fixtures/intake.cjs');

/* The page, in a real browser, over the real shipped assets. */
function installationView(extra={}){
 const now=Date.now(),series={};for(const [key,base]of Object.entries({site_seconds:.3,site_up:1,cpu_used:12,memory_used:40,disk_used:87,http_rate:3.5}))series[key]=Array.from({length:20},(_,i)=>[now-(20-i)*900000,base+(key==='site_up'?0:i/100),base,base+1]);
 series.disk_used=series.disk_used.filter((_,i)=>i<8||i>11);
 return {sourceId:'source-a',name:'gsq <b>staging</b>',environment:'gsq-staging',state:'reporting',lastHeardAt:new Date(now-32000).toISOString(),ageSeconds:32,lateAfterSeconds:180,silentAfterSeconds:600,firstHeardAt:new Date(now-86400000).toISOString(),reports:1204,silentSince:null,heartbeatEndedAt:null,host:'droplet-1',url:'https://gsq.test',health:'degraded',uptimeSeconds:86400,feedError:null,
  checks:[{id:'site',label:'Public site',state:'ok',reading:'Answers in 0.25 s'},{id:'containers',label:'Containers',state:'ok',reading:'3 of 3 running: kernel, postgres, account-runtime'},{id:'disk',label:'Disk',state:'warn',reading:'87% used'},{id:'backup',label:'Nightly backup',state:'bad',reading:'None reported'},{id:'offsite',label:'Off-site copy',state:'unknown',reading:'Not reported here'},{id:'updates',label:'Updates and restarts',state:'unknown',reading:'Not reported'},{id:'monitoring',label:'Its own monitoring',state:'ok',reading:'Reads all 4 of its sources'}],
  firing:[{fingerprint:'f1',alertType:'DiskHigh',severity:'warning',summary:'The disk is over 80% full',startsAt:new Date(now-3600000).toISOString(),deliveryId:'event-a'}],history:{days:1,bucketMinutes:15,since:now-86400000,now,series},...extra};
}
/** A row with no failing check, as the server's assess() calls healthy. */
const well=(extra={})=>installationView({health:'healthy',checks:installationView().checks.map(c=>c.id==='backup'?{...c,state:'ok',reading:'Finished 5 h ago, 12 MB'}:c),...extra});
const late=(extra={})=>installationView({state:'late',ageSeconds:240,...extra});
const silent=(extra={})=>{const silentSince=new Date(Date.now()-3600000).toISOString();return installationView({state:'silent',silentSince,ageSeconds:3600,health:'unknown',...extra});};
const never=(extra={})=>installationView({state:'never',lastHeardAt:null,ageSeconds:null,firstHeardAt:null,reports:0,health:'unknown',host:null,url:null,firing:[],checks:installationView().checks.map(c=>({...c,state:'unknown',reading:'Not reported'})),history:{days:1,bucketMinutes:15,since:Date.now()-86400000,now:Date.now(),series:{}},...extra});
const raised=since=>({fingerprint:'silent-1',alertType:'InstallationSilent',severity:'critical',summary:'gsq has stopped reporting',description:"Operations has not received this installation's heartbeat.",service:null,startsAt:since,lastSeenAt:new Date().toISOString(),deliveryId:'event-a'});
const posted=requests=>requests.some(([m,u])=>m==='POST'&&String(u).endsWith('/ingest/mapping'));
const reads=requests=>requests.filter(([,u])=>String(u).includes('/telemetry')).length;
const sureName=/^Delete its history and stop watching/;
/** Both presses of a stop, past the second button's lock on a double press. */
async function pressStop(page,card){await card.getByRole('button',{name:'Stop watching this installation'}).click();const sure=card.getByRole('button',{name:sureName});await sure.waitFor();await page.waitForTimeout(450);await sure.click();}
const readNow=page=>page.evaluate(()=>document.dispatchEvent(new Event('visibilitychange')));
async function page(run,initial,options={}){
 const http=require('node:http'),fs=require('node:fs'),{chromium}=dependency('playwright');let body={streams:[],limits:{},installations:initial,watch:options.watch===undefined?{lastTickAt:new Date(Date.now()-40000).toISOString(),ageSeconds:40,overdue:false,graceUntil:null}:options.watch};let status=200,postStatus=null;const requests=[];
 const source={id:'source-a',name:'gsq-staging',environment:'gsq-staging',source:'urn:ops:a',mapping:{environment:'/data/environment'}};
 const event={id:'event-a',sourceId:'source-a',decision:'validated',receivedAt:new Date().toISOString(),ingestion:'transactional',reasons:[],normalized:{time:new Date().toISOString(),data:{alertType:'DiskHigh',environment:'gsq-staging',severity:'warning',status:'firing',resource:{kind:'host',scope:'gsq-staging',id:'gsq-staging'}}}};
 const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://localhost'),json=(b,s=200)=>{res.writeHead(s,{'Content-Type':'application/json'});res.end(JSON.stringify(b));};requests.push([req.method,url.pathname+url.search]);
  if(url.pathname==='/api/auth/user')return options.account===null?json({error:'Not here'},404):json(options.account||{authenticated:true,subject:'sub-1',displayName:'Test Person'});if(url.pathname==='/api/tickets')return json({tickets:[]});if(url.pathname==='/api/v1/agent/schedules')return json({schedules:[]});if(url.pathname==='/api/v1/peer-inbox')return json({delegations:[]});
  const prefix='/api/intelligent-operations',route=url.pathname.slice(prefix.length);
  if(url.pathname.startsWith(prefix)&&!route.startsWith('/assets/')&&route!=='/app'){
   if(route==='/telemetry')return status===200?json(body):json({error:'refused'},status);
   if(route.startsWith('/ingest/mapping/')&&req.method==='GET')return json(options.mapped?{sourceId:route.split('/').pop(),source:'urn:ops:a',environment:'gsq-staging',resourceKind:'host',idLabel:'instance',scope:'gsq-staging'}:{mapped:false});
   if(route==='/ingest/mapping'&&req.method==='POST'){if(postStatus)return json({error:'refused'},postStatus);let raw='';req.on('data',c=>raw+=c);req.on('end',()=>{requests.push(['BODY',raw]);body={...body,installations:[]};json({forgotten:true});});return;}
   if(route==='/records')return json({sources:[source],events:[event],inventory:[],processing:[],attempts:[]});if(route==='/pipeline')return json({policies:[],bindings:[],decisions:[],symptoms:[],evidenceWork:[],correlations:[]});if(route==='/investigations')return json({items:[]});if(route==='/topology')return json(options.graph||{asOf:new Date().toISOString(),assets:[],relationships:[],collections:[]});if(route==='/topology/discovery')return json(options.discovery||{enabled:false});
   if(route==='/pipeline/processing')return json({config:{enabled:false,sourceIds:[],batchSize:10,maxAttempts:8,retrySeconds:30,revision:0},scheduleName:'fixture',jobs:[],limit:200,leaseSeconds:120});if(route==='/executions')return json({items:[]});if(route==='/delegations')return json({items:[]});if(route==='/anomaly')return json({baselines:[],cursors:[],config:{}});return json({error:'Fixture does not implement this action'},404);
  }
  let file;if(route==='/app')file=path.join(root,'experience/index.html');else if(route.startsWith('/assets/')){const name=path.basename(route);file=path.join(root,name==='operations.css'?'ui':'experience',name);if(['replay-scenarios.js','response-artifacts.js','anomaly-detector.js'].includes(name))file=path.join(root,'ui',name);}
  if(file&&fs.existsSync(file)){res.setHeader('Content-Type',file.endsWith('.js')?'text/javascript':file.endsWith('.css')?'text/css':'text/html');return res.end(fs.readFileSync(file));}
  res.writeHead(404);res.end();
 });
 let browser;
 try{await new Promise(r=>server.listen(0,'127.0.0.1',r));browser=await chromium.launch({headless:true,args:['--disable-gpu']});const context=await browser.newContext({viewport:options.viewport||{width:1440,height:1000},...options.context}),tab=await context.newPage();tab.setDefaultTimeout(10000);const errors=[];tab.on('pageerror',e=>errors.push(e.message));
  const origin='http://127.0.0.1:'+server.address().port,base=origin+'/api/intelligent-operations/app';
  /** The page inside a real same-origin iframe, the way the shell hosts it. */
  const framed=async hash=>{await tab.route(origin+'/wrapper',r=>r.fulfill({contentType:'text/html',body:'<!doctype html><html><body style="margin:0;height:100vh"><iframe id="f" src="'+base+hash+'" style="width:100%;height:100%;border:0"></iframe></body></html>'}));await tab.goto(origin+'/wrapper');return (await tab.waitForSelector('#f')).contentFrame();};
  await run({page:tab,context,base,framed,requests,errors,set:next=>{body={...body,...next};},refuse:code=>{status=code;},refusePost:code=>{postStatus=code;}});assert.deepEqual(errors,[]);
 }finally{await browser?.close();server.closeAllConnections();await new Promise(r=>server.close(r));}
}
