 const chart=card.locator('.installation-chart[data-metric=site_seconds]');const box=await chart.locator('svg').boundingBox();await page.mouse.move(box.x+box.width*.5,box.y+box.height*.4);const tip=chart.locator('.installation-tip');await tip.waitFor();assert.match(await tip.textContent(),/\d\.\d\d s.*Low 0\.30 s, high 1\.30 s/);assert.equal(await chart.locator('.installation-hair').getAttribute('visibility'),'visible');
